package com.xrglasses.launcher;
import java.io.*; import java.util.concurrent.TimeUnit;
public final class RootBridge { public enum Status{SUCCESS,ROOT_DENIED,TIMEOUT,COMMAND_UNSUPPORTED,FAILED} public static final class Result{public final Status status;public final int exitCode;public final String stdout,stderr;Result(Status s,int c,String o,String e){status=s;exitCode=c;stdout=o;stderr=e;}public boolean ok(){return status==Status.SUCCESS;}public String toString(){return status+"("+exitCode+"): "+stdout+" "+stderr;}} public boolean isRootAvailable(){return execute("id",1500).ok();} public Result execute(String command,long timeout){try{Process p=new ProcessBuilder("su","-c",command).redirectErrorStream(false).start();if(!p.waitFor(timeout,TimeUnit.MILLISECONDS)){p.destroyForcibly();return new Result(Status.TIMEOUT,-1,"","timeout");}String o=read(p.getInputStream()),e=read(p.getErrorStream());int c=p.exitValue();if(c==0)return new Result(Status.SUCCESS,c,o,e);if(e.contains("not found")||e.contains("unknown command"))return new Result(Status.COMMAND_UNSUPPORTED,c,o,e);if(e.contains("permission denied")||e.contains("denied"))return new Result(Status.ROOT_DENIED,c,o,e);return new Result(Status.FAILED,c,o,e);}catch(Exception e){return new Result(Status.FAILED,-1,"",e.toString());}} public Result executeInputCommand(String c){return execute("cmd input "+c,1200);} public Result setTemporaryBrightness(int v){return execute("settings put system screen_brightness "+Math.max(1,Math.min(255,v)),1500);} public Result restoreBrightness(int v){return setTemporaryBrightness(v);} public String getBridgeDiagnostics(){return execute("id; cmd input help | head -n 30",2000).toString();} private static String read(InputStream s)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(s));StringBuilder b=new StringBuilder();String l;while((l=r.readLine())!=null)b.append(l).append('\n');return b.toString().trim();} }